public sealed class ObfuscatedTO
{
    private readonly IDataProtector _protector;
    [JsonIgnore] public Dictionary<string, string>? Protected { get; private set; }
    public byte[]? Sealed { get; private set; }        // wire form carries only this

    public void Seal()
    {
        Sealed = _protector.Protect(JsonSerializer.SerializeToUtf8Bytes(Protected!));
        Protected = null;                              // drop the plaintext view
    }
    public override string ToString() => "ObfuscatedTO";   // record printing would leak
}

