public sealed class ProtectedMapConverter : JsonConverter<ProtectedMap>
{
    private readonly AesGcm _aes;                        // 32-byte key from the key store
    public override void Write(Utf8JsonWriter w, ProtectedMap value, JsonSerializerOptions o)
    {
        var nonce = RandomNumberGenerator.GetBytes(12);   // unique per seal
        var tag = new byte[16];
        var plain = JsonSerializer.SerializeToUtf8Bytes(value);
        var cipher = new byte[plain.Length];
        _aes.Encrypt(nonce, plain, cipher, tag);
        w.WriteBase64StringValue([.. nonce, .. tag, .. cipher]);   // sealed bytes on the wire
    }
    // Read: split nonce/tag/cipher, _aes.Decrypt, then deserialize the map.
}
